using Microsoft.Extensions.AI;
using OpenAI;
using System.ComponentModel;
using System.Text.Json;

Console.WriteLine("Research Agent Starting...");

var topic = args.Length > 0 ? string.Join(' ', args) : "the impact of quantum computing on cryptography";
Console.WriteLine($"Researching topic: {topic}\n");

// Configure the AI client
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "sk-placeholder";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient();

// Create tools
var researchTools = new ResearchTools();
var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

// Run the agent loop
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly.
        Use the SearchWeb tool to find information from multiple angles.
        Use the TakeNote tool to record important findings as you go.
        Perform at least 3 searches on different aspects of the topic.
        After gathering enough information, use GetNotes to review your notes,
        then provide a comprehensive summary of your findings.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

const int maxIterations = 15;
var iteration = 0;

while (iteration++ < maxIterations)
{
    var response = await chatClient.GetResponseAsync(messages, chatOptions);

    // Add the assistant response to the conversation
    messages.AddRange(response.Messages);

    // Check if there are tool calls to process
    if (response.Messages.Any(m => m.Contents.OfType<FunctionCallContent>().Any()))
    {
        foreach (var message in response.Messages)
        {
            foreach (var functionCall in message.Contents.OfType<FunctionCallContent>())
            {
                Console.WriteLine($"  [Tool Call] {functionCall.Name}({TruncateArgs(functionCall.Arguments)})");

                var result = await functionCall.InvokeAsync(chatOptions.Tools.OfType<AIFunction>());
                messages.Add(new ChatMessage(ChatRole.Tool, [result]));
            }
        }
    }
    else
    {
        // No more tool calls — agent has finished
        var finalText = string.Join("", response.Messages.Select(m => m.Text).Where(t => t != null));
        Console.WriteLine("\n========== RESEARCH SUMMARY ==========\n");
        Console.WriteLine(finalText);
        Console.WriteLine("\n=======================================");
        break;
    }
}

if (iteration > maxIterations)
{
    Console.WriteLine("\n[Agent reached maximum iterations]");
}

Console.WriteLine($"\nNotes collected: {researchTools.NoteCount}");

static string TruncateArgs(IDictionary<string, object?>? args)
{
    if (args is null || args.Count == 0) return "";
    var json = JsonSerializer.Serialize(args);
    return json.Length > 80 ? json[..80] + "..." : json;
}

/// <summary>
/// Tools available to the research agent.
/// </summary>
public class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    public int NoteCount => _notes.Count;

    [Description("Search the web for information on a query. Returns search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            // Use a public search API (DuckDuckGo instant answer API)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await _httpClient.GetStringAsync(url);
            var doc = JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract
            var abstractText = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"Summary: {abstractText}");

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var related))
            {
                foreach (var item in related.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text))
                        results.Add($"- {text.GetString()}");
                }
            }

            if (results.Count == 0)
                return $"No detailed results found for '{query}'. Try a more specific search.";

            return string.Join("\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to record an important finding during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        return $"Note saved (total notes: {_notes.Count}).";
    }

    [Description("Retrieve all notes taken so far during this research session.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        var result = $"=== Research Notes ({_notes.Count} total) ===\n";
        for (int i = 0; i < _notes.Count; i++)
        {
            result += $"\n[{i + 1}] {_notes[i]}\n";
        }
        return result;
    }
}

